MSG_ComposeFormat requestedComposeFormat = fields.format;

// Override the compose format only for URLs that do not require a
// specific format.
if (requestedComposeFormat == nsIMsgCompFormat::Default) {
  requestedComposeFormat = aFormat;
}
bool composeHTMLFormat;
DetermineComposeHTML(aIdentity, requestedComposeFormat, &composeHTMLFormat);

// If there was an 'html-body' param, finding it will have set HTML
// format, so we try to use it first. If it's empty, but we are composing
// in HTML because of the user's prefs, the 'body' param needs to be
// escaped, since it's supposed to be plain text.
nsString rawBody;
nsAutoString sanitizedBody;
if (fields.html.IsEmpty()) {
  if (composeHTMLFormat) {
    nsCString escaped;
    nsAppendEscapedHTML(fields.body, escaped);
    CopyUTF8toUTF16(escaped, sanitizedBody);
  } else {
    CopyUTF8toUTF16(fields.body, rawBody);
  }
} else {
  CopyUTF8toUTF16(fields.html, rawBody);
}

if (!rawBody.IsEmpty() && composeHTMLFormat) {
  // For security reasons, we must sanitize the message body before
  // accepting any HTML.
  rv = HTMLSanitize(rawBody, sanitizedBody);  // from mimemoz2.h
  if (NS_FAILED(rv)) {
    // Something went wrong with parsing; fall back to plain text compose.
    composeHTMLFormat = false;
  }

    Assert.equal(
      cwc.gMsgCompose.identity,
      identity,
      "The correct identity should be selected."
    );
    console.log(identity.composeHtml);
    if (htmlFields) {
      Assert.equal(
        cwc.gMsgCompose.composeHTML,
        true,
        "Any click on 'mailto' link containing HTML fields: Compose HTML should be true."
      );
    } else if (!shift) {
      Assert.equal(
        cwc.gMsgCompose.composeHTML,
        identity.composeHtml,
        "Compose HTML should match the identity's setting."
      );
    } else {
      Assert.equal(
        cwc.gMsgCompose.composeHTML,
        !identity.composeHtml,
        "Shift-click: Compose HTML should match the opposite of the identity's setting."
      );
    }
    await close_compose_window(cwc);
  };

  identityA0.composeHtml = formatA0;
  identityB0.composeHtml = formatB0;
  identityB1.composeHtml = formatB1;

  // Test the identity for account A.
  await selectMessageInFolder(inboxA);
  await clickMailtoLink(identityA0);
  await clickMailtoLink(identityA0, true);

  // Test a 'mailto' link containing a 'html-body' field.
  await selectMessageInFolder(inboxA, 1);
  await clickMailtoLink(identityA0, false, true);
  await clickMailtoLink(identityA0, true, true);

  // Test the first identity for account B.
  await selectMessageInFolder(inboxB);
  await clickMailtoLink(identityB0);
  await clickMailtoLink(identityB0, true);

  // Test the second identity for account B.
  await selectMessageInFolder(inboxB, 1);
  await clickMailtoLink(identityB1);
  await clickMailtoLink(identityB1, true);
};

await subTest(true, false, true);
await subTest(false, true, false);
